//! RUST-013 slice r013-ingestcmds: replays the Go-owned process fixture
//! (`testdata/port/cli/cli-ingest-bodies-process.json`, generated by
//! `cmd/symdesk/ingest_bodies_process_port_test.go`) for the `ingest`, `mail`,
//! `meeting`, `rules` and `clip` command bodies against the Rust binary.
//! Every step runs in a disposable HOME/XDG/cwd with a disposable vault and
//! compares exit code, stdout, stderr and — for snapshot cases — the vault
//! tree and the text files below HOME after the step. Loopback fakes replace
//! every network peer.
#![cfg(unix)]

#[path = "../../test-support/process_env.rs"]
mod process_env;
use process_env::IsolatedEnvironment;

#[path = "support/process_root.rs"]
mod process_root;

#[path = "support/cli_normalize.rs"]
mod cli_normalize;

#[path = "support/embedding_fake.rs"]
mod embedding_fake;

#[path = "support/ingest_normalize.rs"]
mod ingest_normalize;

#[path = "support/ingest_fakes.rs"]
mod ingest_fakes;

use std::{
    collections::BTreeMap,
    fs,
    io::Write,
    net::TcpListener,
    path::{Path, PathBuf},
    process::Command,
    time::{SystemTime, UNIX_EPOCH},
};

use serde::Deserialize;

/// Cases and steps recorded in the committed fixture. A fixture that changes
/// without these numbers changing is rejected, and a replay that skips cases
/// or steps cannot pass.
const EXPECTED_CASES: usize = 41;
const EXPECTED_STEPS: usize = 565;
/// Steps whose Go process exited non-zero: the negative half of the suite.
const EXPECTED_FAILING_STEPS: usize = 296;
/// Steps that also compare the vault tree / HOME text files after the step.
const EXPECTED_VAULT_SNAPSHOTS: usize = 261;
const EXPECTED_HOME_SNAPSHOTS: usize = 192;

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    cases: Vec<Case>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    #[serde(default)]
    files: BTreeMap<String, String>,
    #[serde(default)]
    cwd_files: BTreeMap<String, String>,
    #[serde(default)]
    home_files: Option<BTreeMap<String, String>>,
    #[serde(default)]
    env: BTreeMap<String, String>,
    #[serde(default)]
    servers: Vec<String>,
    #[serde(default)]
    contacts: Vec<Contact>,
    #[serde(default)]
    skip_index: bool,
    #[serde(default)]
    no_vault: bool,
    #[serde(default)]
    snapshot_vault: bool,
    #[serde(default)]
    snapshot_home: bool,
    #[serde(default)]
    canaries: Vec<String>,
    steps: Vec<Step>,
}

#[derive(Deserialize)]
struct Contact {
    id: String,
    name: String,
    /// `person` or `organization`.
    kind: String,
}

/// Lets the binary create and migrate the contact store (a lookup of an
/// unknown id), then inserts the seed rows below the case HOME.
fn seed_contacts(binary: &str, home: &Path, cwd: &Path, vault: &Path, contacts: &[Contact]) {
    let _ = run(
        binary,
        home,
        cwd,
        &[],
        &[
            "--vault".to_owned(),
            vault.to_string_lossy().into_owned(),
            "meeting".to_owned(),
            "participant".to_owned(),
            "contact".to_owned(),
            "seed-probe".to_owned(),
        ],
        "",
    );
    fn find(directory: &Path) -> Option<PathBuf> {
        for entry in fs::read_dir(directory).ok()?.flatten() {
            let path = entry.path();
            if path.is_dir() {
                if let Some(found) = find(&path) {
                    return Some(found);
                }
            } else if entry.file_name() == "symrelate.db" {
                return Some(path);
            }
        }
        None
    }
    let database = find(home).expect("the contact store was created below HOME");
    let db = rusqlite::Connection::open(database).expect("open the contact store");
    for contact in contacts {
        let statement = if contact.kind == "organization" {
            "INSERT INTO organizations (id, name) VALUES (?, ?)"
        } else {
            "INSERT INTO persons (id, display_name) VALUES (?, ?)"
        };
        db.execute(statement, (&contact.id, &contact.name))
            .expect("seed a contact");
    }
}

#[derive(Deserialize, Clone)]
struct Step {
    args: Vec<String>,
    #[serde(default)]
    stdin: String,
    exit_code: i32,
    stdout: String,
    stderr: String,
    #[serde(default)]
    vault: Option<BTreeMap<String, String>>,
    #[serde(default)]
    home: Option<BTreeMap<String, String>>,
}

fn fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(include_str!(
        "../../../testdata/port/cli/cli-ingest-bodies-process.json"
    ))
    .expect("decode Go-owned CLI ingest bodies fixture");
    assert_eq!(fixture.schema_version, 1);
    fixture
}

struct Run {
    exit: i32,
    stdout: String,
    stderr: String,
}

fn base_command(binary: &str, home: &Path, cwd: &Path) -> Command {
    let mut command = Command::new(binary);
    command
        .current_dir(cwd)
        .isolated_env()
        .envs(
            std::env::vars().filter(|(name, _)| {
                matches!(name.as_str(), "PATH" | "SYSTEMROOT" | "TEMP" | "TMP")
            }),
        )
        .env("TZ", "UTC")
        .env("HOME", home)
        .env("USERPROFILE", home)
        .env("XDG_CONFIG_HOME", home.join("config"))
        .env("XDG_CACHE_HOME", home.join("cache"))
        .env("XDG_DATA_HOME", home.join("data"));
    command
}

fn run(
    binary: &str,
    home: &Path,
    cwd: &Path,
    env: &[(String, String)],
    args: &[String],
    stdin: &str,
) -> Run {
    let mut command = base_command(binary, home, cwd);
    command
        .envs(env.iter().map(|(name, value)| (name, value)))
        .args(args)
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = command.spawn().expect("spawn Rust symdesk process");
    let mut pipe = child.stdin.take().expect("stdin pipe");
    // The child may exit without reading stdin; a broken pipe is fine.
    let _ = pipe.write_all(stdin.as_bytes());
    drop(pipe);
    let output = child.wait_with_output().expect("wait for Rust symdesk");
    Run {
        exit: output.status.code().unwrap_or(-1),
        stdout: String::from_utf8(output.stdout).expect("UTF-8 stdout"),
        stderr: String::from_utf8(output.stderr).expect("UTF-8 stderr"),
    }
}

fn write_files(base: &Path, files: &BTreeMap<String, String>, replace: &dyn Fn(&str) -> String) {
    for (name, content) in files {
        let target = base.join(name);
        fs::create_dir_all(target.parent().expect("file parent")).expect("make parent");
        fs::write(&target, replace(content)).expect("write case file");
        // Fake sibling-tool scripts live below `bin/` and must be executable.
        if name.starts_with("bin/") || name.starts_with("managed/") {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&target, fs::Permissions::from_mode(0o700))
                .expect("make fake tool executable");
        }
    }
}

fn files_under(directory: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = fs::read_dir(directory) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let Ok(kind) = entry.file_type() else {
            continue;
        };
        if kind.is_dir() {
            files_under(&path, out);
        } else if kind.is_file() && entry.file_name() != ".DS_Store" {
            // .DS_Store is Finder metadata of the host, never command output.
            out.push(path);
        }
    }
}

/// Occurrences of `canary` in the case's streams and every file below `root`.
fn canary_hits(canary: &str, observed: &Run, root: &Path) -> usize {
    let count = |bytes: &[u8]| String::from_utf8_lossy(bytes).matches(canary).count();
    let mut files = Vec::new();
    files_under(root, &mut files);
    count(observed.stdout.as_bytes())
        + count(observed.stderr.as_bytes())
        + files
            .iter()
            .map(|path| count(&fs::read(path).unwrap_or_default()))
            .sum::<usize>()
}

fn closed_port() -> String {
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind loopback");
    let port = listener.local_addr().expect("local address").port();
    drop(listener);
    port.to_string()
}

/// Every UTF-8 regular file below `directory` (mirrors `snapshotIngestTree`).
fn snapshot(
    directory: &Path,
    root: &Path,
    canonical: &Path,
    closed_port: &str,
    skip: &dyn Fn(&str) -> bool,
) -> BTreeMap<String, String> {
    let mut files = Vec::new();
    files_under(directory, &mut files);
    files
        .into_iter()
        .filter_map(|path| {
            let relative = path
                .strip_prefix(directory)
                .expect("below directory")
                .to_string_lossy()
                .replace('\\', "/");
            let relative = cli_normalize::journal_key(&relative);
            if skip(&relative) {
                return None;
            }
            // History content ids hash notes that embed the wall clock: only
            // the manifests (proof that a snapshot was taken) are compared.
            if relative.starts_with(".symdesk/history/objects/") {
                return None;
            }
            if relative.starts_with(".symdesk/history/manifest/") {
                return Some((
                    ingest_normalize::normalize(&relative, root, canonical),
                    "(present)".to_owned(),
                ));
            }
            let data = fs::read(&path).expect("read case file");
            let text = String::from_utf8(data).ok()?;
            Some((
                ingest_normalize::normalize(&relative, root, canonical),
                // The case's closed loopback port is random per run.
                ingest_normalize::normalize(&text, root, canonical)
                    .replace(closed_port, "$CLOSED_PORT"),
            ))
        })
        .collect()
}

fn home_skip(relative: &str) -> bool {
    relative.starts_with("cache/")
        || relative.starts_with("bin/")
        || relative.contains(".db")
        || relative.starts_with(".config/symseek/")
}

fn matches_go(step: &Step, observed: &Run, root: &Path, canonical: &Path) -> bool {
    observed.exit == step.exit_code
        && ingest_normalize::normalize(&observed.stdout, root, canonical) == step.stdout
        && ingest_normalize::normalize(&observed.stderr, root, canonical) == step.stderr
}

fn tree_differences(
    expected: &BTreeMap<String, String>,
    actual: &BTreeMap<String, String>,
) -> Vec<String> {
    let mut differences = Vec::new();
    for key in expected.keys().chain(actual.keys()) {
        if expected.get(key) != actual.get(key) {
            differences.push(format!(
                "    {key}\n      go:   {:?}\n      rust: {:?}",
                expected.get(key),
                actual.get(key)
            ));
        }
    }
    differences.dedup();
    differences
}

#[test]
fn cli_ingest_bodies_match_go_process_contract() {
    let fixture = fixture();
    let steps = || fixture.cases.iter().flat_map(|case| &case.steps);
    assert_eq!(fixture.cases.len(), EXPECTED_CASES);
    assert_eq!(steps().count(), EXPECTED_STEPS);
    assert_eq!(
        steps().filter(|step| step.exit_code != 0).count(),
        EXPECTED_FAILING_STEPS,
        "the recorded suite keeps its negative half"
    );
    // An empty tree is omitted from the JSON, so snapshot steps are counted
    // through their case.
    let snapshot_steps = |select: fn(&Case) -> bool| {
        fixture
            .cases
            .iter()
            .filter(|case| select(case))
            .map(|case| case.steps.len())
            .sum::<usize>()
    };
    assert_eq!(
        snapshot_steps(|case| case.snapshot_vault),
        EXPECTED_VAULT_SNAPSHOTS
    );
    assert_eq!(
        snapshot_steps(|case| case.snapshot_home),
        EXPECTED_HOME_SNAPSHOTS
    );
    let binary = env!("CARGO_BIN_EXE_symdesk");
    let base: PathBuf = std::env::temp_dir().join(format!(
        "symdesk-cli-ingest-bodies-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock after epoch")
            .as_nanos()
    ));
    fs::create_dir(&base).expect("make isolated test directory");

    let (mut executed_cases, mut executed_steps) = (0, 0);
    let (mut vault_snapshots, mut home_snapshots) = (0, 0);
    let mut failures = Vec::new();
    for case in &fixture.cases {
        executed_cases += 1;
        let root = base.join(&case.name);
        fs::create_dir_all(&root).expect("make case root");
        let root = process_root::canonical_root(&root);
        let (vault, home, cwd) = (root.join("vault"), root.join("home"), root.join("cwd"));
        for directory in [&vault, &home, &cwd] {
            fs::create_dir_all(directory).expect("make case directory");
        }
        let canonical = fs::canonicalize(&root).expect("canonical case root");
        let root_text = root.to_string_lossy().into_owned();

        let embeddings = embedding_fake::EmbeddingFake::start();
        let mut placeholders = BTreeMap::from([
            ("$CLOSED_PORT".to_owned(), closed_port()),
            ("$EMBED_URL".to_owned(), embeddings.url.clone()),
        ]);
        let _servers: Vec<_> = case
            .servers
            .iter()
            .map(|name| ingest_fakes::start(name, &mut placeholders))
            .collect();
        let replace = |value: &str| {
            let mut keys: Vec<&String> = placeholders.keys().collect();
            keys.sort_by_key(|key| std::cmp::Reverse(key.len()));
            let mut value = value.to_owned();
            for key in keys {
                value = value.replace(key.as_str(), &placeholders[key]);
            }
            process_root::expand_argument(&value, &root_text)
        };
        write_files(&vault, &case.files, &replace);
        write_files(&cwd, &case.cwd_files, &replace);
        match &case.home_files {
            Some(files) => write_files(&home, files, &replace),
            None => write_files(
                &home,
                &BTreeMap::from([(
                    ".config/symseek/config.toml".to_owned(),
                    "ollama_url = \"$EMBED_URL/api/embeddings\"\nembedding_dim = 3\ntimeout_seconds = 2\nretry_count = 0\nmodel = \"fixture\"\n"
                        .to_owned(),
                )]),
                &replace,
            ),
        }
        let env: Vec<(String, String)> = case
            .env
            .iter()
            .map(|(name, value)| (name.clone(), replace(value)))
            .collect();
        if !case.skip_index && !case.no_vault {
            let setup = run(
                binary,
                &home,
                &cwd,
                &[],
                &[
                    "--vault".to_owned(),
                    vault.to_string_lossy().into_owned(),
                    "index".to_owned(),
                ],
                "",
            );
            assert_eq!(setup.exit, 0, "{} setup index: {}", case.name, setup.stderr);
        }
        if !case.contacts.is_empty() {
            seed_contacts(binary, &home, &cwd, &vault, &case.contacts);
        }
        for step in &case.steps {
            let mut args = Vec::new();
            if !case.no_vault {
                args.push("--vault".to_owned());
                args.push(vault.to_string_lossy().into_owned());
            }
            args.extend(step.args.iter().map(|argument| replace(argument)));
            let observed = run(binary, &home, &cwd, &env, &args, &replace(&step.stdin));
            let label = format!("{} {:?}", case.name, step.args);
            let stdout = ingest_normalize::normalize(&observed.stdout, &root, &canonical);
            let stderr = ingest_normalize::normalize(&observed.stderr, &root, &canonical);
            if stdout != step.stdout {
                failures.push(format!(
                    "{label} stdout\n  go:   {:?}\n  rust: {stdout:?}",
                    step.stdout
                ));
            }
            if stderr != step.stderr {
                failures.push(format!(
                    "{label} stderr\n  go:   {:?}\n  rust: {stderr:?}",
                    step.stderr
                ));
            }
            if observed.exit != step.exit_code {
                failures.push(format!(
                    "{label} exit go {} rust {}",
                    step.exit_code, observed.exit
                ));
            }
            if case.snapshot_vault {
                vault_snapshots += 1;
                let expected = step.vault.clone().unwrap_or_default();
                let tree = snapshot(
                    &vault,
                    &root,
                    &canonical,
                    &placeholders["$CLOSED_PORT"],
                    &|_| false,
                );
                if tree != expected {
                    failures.push(format!(
                        "{label} vault tree\n{}",
                        tree_differences(&expected, &tree).join("\n")
                    ));
                }
            }
            if case.snapshot_home {
                home_snapshots += 1;
                let expected = step.home.clone().unwrap_or_default();
                let tree = snapshot(
                    &home,
                    &root,
                    &canonical,
                    &placeholders["$CLOSED_PORT"],
                    &home_skip,
                );
                if tree != expected {
                    failures.push(format!(
                        "{label} HOME files\n{}",
                        tree_differences(&expected, &tree).join("\n")
                    ));
                }
            }
            for canary in &case.canaries {
                if canary_hits(canary, &observed, &cwd) != 0
                    || canary_hits(canary, &observed, &vault) != 0
                {
                    failures.push(format!("{label} leaks a canary into its output"));
                }
            }
            executed_steps += 1;
        }
    }
    let _ = fs::remove_dir_all(&base);
    assert!(
        failures.is_empty(),
        "{} of {executed_steps} steps differ from Go:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert_eq!(executed_steps, EXPECTED_STEPS, "every fixture step ran");
    assert_eq!(executed_cases, EXPECTED_CASES, "every fixture case ran");
    assert_eq!(vault_snapshots, EXPECTED_VAULT_SNAPSHOTS);
    assert_eq!(home_snapshots, EXPECTED_HOME_SNAPSHOTS);
}

/// Negative control: the comparison used above must reject a changed byte,
/// a changed exit code and a swapped stream.
#[test]
fn comparison_rejects_tampered_go_observations() {
    let fixture = fixture();
    let step = fixture
        .cases
        .iter()
        .flat_map(|case| &case.steps)
        .find(|step| step.exit_code == 1 && !step.stderr.is_empty())
        .expect("a failing step with stderr");
    let root = Path::new("/nonexistent-root");
    let observed = Run {
        exit: step.exit_code,
        stdout: step.stdout.clone(),
        stderr: step.stderr.clone(),
    };
    assert!(matches_go(step, &observed, root, root));
    let mut changed = step.clone();
    changed.stderr.push('x');
    assert!(!matches_go(&changed, &observed, root, root), "changed byte");
    let mut changed = step.clone();
    changed.exit_code = 0;
    assert!(
        !matches_go(&changed, &observed, root, root),
        "changed exit code"
    );
    let swapped = Run {
        exit: observed.exit,
        stdout: observed.stderr.clone(),
        stderr: observed.stdout.clone(),
    };
    assert!(!matches_go(step, &swapped, root, root), "swapped streams");
}

/// Negative control for the tree halves: a snapshot with a changed or a
/// missing file must differ from the recorded one.
#[test]
fn tree_snapshot_comparison_rejects_a_changed_file() {
    let fixture = fixture();
    let recorded = fixture
        .cases
        .iter()
        .flat_map(|case| &case.steps)
        .find_map(|step| step.home.as_ref().filter(|tree| !tree.is_empty()))
        .expect("a recorded HOME snapshot");
    let mut changed = recorded.clone();
    let key = changed.keys().next().cloned().expect("a file");
    changed.get_mut(&key).expect("file").push('x');
    assert!(!tree_differences(recorded, &changed).is_empty());
    let mut missing = recorded.clone();
    missing.remove(&key);
    assert!(!tree_differences(recorded, &missing).is_empty());
    assert!(tree_differences(recorded, recorded).is_empty());
}

#[test]
fn normalization_matches_the_go_regexps() {
    assert_eq!(
        ingest_normalize::normalize_random(&"a".repeat(24)),
        "$RAND24"
    );
    assert_eq!(
        ingest_normalize::normalize_random(&"a".repeat(30)),
        "$RAND24aaaaaa"
    );
    assert_eq!(
        ingest_normalize::normalize_toml("e: toml: line 3 (last key \"x\"): bad\nnext"),
        "e: toml: line $TOML\nnext"
    );
    assert_eq!(
        ingest_normalize::normalize_toml("toml: line 12\""),
        "toml: line $TOML"
    );
    assert_eq!(
        ingest_normalize::normalize_rfc3339("a 2026-01-02T03:04:05.123Z b"),
        "a $RFC3339 b"
    );
}
